def delete_quote(phrase):    first = phrase.find('<')    i =first+1    last = phrase.find('>')    while i < len(phrase):        if phrase[i] == '<':            if phrase[i] < last:                first = i        i+=1    if first < 0 or last < 0:        return phrase    else:        return phrase[:first] + phrase[last + 1:]data = input()nex = (data.find('<') >= 0 and data.find('>') > 0) and (data.find('<') < data.find('>'))while nex:    data = delete_quote(data)    nex = (data.find('<') >= 0 and data.find('>') > 0) and (data.find('<') < data.find('>'))print(data)